module Exchange(n: number, choose: boolean) {
 const Poison: point = coordinate(x: 1 / 0, y: 0)
 const AA: point[] = [(@n, 1), @Poison]
 const BB: point[] = [(@n + 10, 2)]
 const CC: point[] = [(@n + 30, 3), (@n + 40, 4)]
 const Ticks: number[] = [7]
 for Tick in @Ticks carry A: point[] = @AA carry B: point[] = @BB carry C: point[] = @CC {
 next A = @B
 next B = @C
 next C = @A
 }
 export point OutA = from(source: @A[0])
 export point OutB = from(source: @B[1])
 export point OutC = from(source: @C[0])
 export const Size: number = @C.length
}
instance One = Exchange(n: 7, choose: true)
instance Two = Exchange(n: 41, choose: true)
const N: number = @One::Size
const M: number = @Two::Size

