module Change(n: number) {
 const Straight: line = segment(start: (@n, 0), end: (@n + 3, 4))
 const Bent: path = polyline(points: [(@n + 10, 0), (@n + 13, 0), (@n + 13, 12)], closed: false)
 const Ticks: number[] = [1]
 for Tick in @Ticks carry Edge: line = @Straight carry Route: path = @Bent carry End: point = coordinate(x: @n, y: 1) {
  const Rebuilt: line = segment(start: @Edge.end, end: @Route.end)
  next End = @Route.end
  next Edge = @Rebuilt
  next Route = @Edge
 }
 export point Observed = from(source: @End)
 export line Result = from(source: @Edge)
 export const Size: number = @Route.length
}
instance One = Change(n: 7)
instance Two = Change(n: 31)
const X: number = @One::Size
const Y: number = @Two::Size

