module Staged(n: number, select: boolean) {
 line Seed = polyline(points: [(@n, 0), (@n + 3, 0), (@n + 3, 4)], closed: false)
 move Seed as shifted (from: (0, 0), to: (5, 7))
 const Bad: path = segment(start: (0, 0), end: (1 / 0, 0))
 const Paths: path[] = if (@select) { [@Seed.shifted] } else { [@Bad] }
 for Tick in range(min: 0, max: 0, step: 1) carry End: point = coordinate(x: 0, y: 0) carry Held: path[] = @Paths {
  const Selected: path = @Held[0]
  next End = @Selected.end
  next Held = @Paths
 }
 export point Observed = from(source: @End)
}
instance One = Staged(n: 11, select: true)
instance Two = Staged(n: 37, select: true)

